-- SCMS demo DB inventory: READ ONLY, no schema changes, no passwords/OTP/token values or business row dumps.
-- Run the whole file on the Supabase DB being reviewed. Return the one scms_demo_db_audit cell (all three reports are nested inside).
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='120s';
SET LOCAL lock_timeout='5s';
SET LOCAL TIME ZONE 'Asia/Ho_Chi_Minh';
SET LOCAL search_path=pg_catalog,public;
WITH schema_report AS (
WITH tables AS (
 SELECT c.oid,n.nspname AS schema_name,c.relname AS table_name,c.relkind,c.relrowsecurity,c.relforcerowsecurity
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')
)
SELECT jsonb_build_object('report_kind','schema_inventory','captured_at',statement_timestamp(),'database',current_database(),
 'server_version',current_setting('server_version'),'read_only',current_setting('transaction_read_only'),
 'schemas',(SELECT jsonb_agg(nspname ORDER BY nspname) FROM pg_namespace WHERE nspname!~'^pg_' AND nspname<>'information_schema'),
 'extensions',(SELECT jsonb_agg(jsonb_build_object('name',extname,'version',extversion,'schema',n.nspname) ORDER BY extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
 'tables',coalesce((SELECT jsonb_agg(jsonb_build_object('name',t.table_name,'kind',t.relkind,'rls',t.relrowsecurity,'force_rls',t.relforcerowsecurity,
  'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,
   'default',CASE WHEN a.attname~*'(password|secret|token|credential|otp|api_key)' AND d.adbin IS NOT NULL THEN '<sensitive default omitted>' ELSE pg_get_expr(d.adbin,d.adrelid) END) ORDER BY a.attnum)
   FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped),
  'constraints',(SELECT jsonb_agg(jsonb_build_object('name',c.conname,'kind',c.contype,'validated',c.convalidated,'deferrable',c.condeferrable,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY c.conname) FROM pg_constraint c WHERE c.conrelid=t.oid),
  'indexes',(SELECT jsonb_agg(jsonb_build_object('name',ci.relname,'valid',i.indisvalid,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY ci.relname) FROM pg_index i JOIN pg_class ci ON ci.oid=i.indexrelid WHERE i.indrelid=t.oid),
  'triggers',(SELECT jsonb_agg(jsonb_build_object('name',tr.tgname,'enabled',tr.tgenabled,'function_schema',pn.nspname,'function_name',p.proname,'definition',CASE WHEN octet_length(tr.tgargs)>0 THEN '<trigger arguments omitted>' ELSE pg_get_triggerdef(tr.oid,true) END) ORDER BY tr.tgname) FROM pg_trigger tr JOIN pg_proc p ON p.oid=tr.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE tr.tgrelid=t.oid AND NOT tr.tgisinternal)
 ) ORDER BY t.table_name) FROM tables t),'[]'::jsonb),
 'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'kind',p.prokind,'security_definer',p.prosecdef,'volatility',p.provolatile,'body_md5',md5(p.prosrc),'settings_names',(SELECT array_agg(split_part(x,'=',1)) FROM unnest(p.proconfig) x)) ORDER BY p.proname,p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'),
 'sequences',(SELECT jsonb_agg(jsonb_build_object('name',sequencename,'type',data_type,'start',start_value,'increment',increment_by,'last',last_value) ORDER BY sequencename) FROM pg_sequences WHERE schemaname='public'),
 'views',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'definition_md5',md5(pg_get_viewdef(c.oid,true))) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m')),
 'policies',(SELECT jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'qual_md5',md5(qual),'with_check_md5',md5(with_check)) ORDER BY tablename,policyname) FROM pg_policies WHERE schemaname='public'),
 'table_grants',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'grantee',grantee,'privilege',privilege_type,'grantable',is_grantable) ORDER BY table_name,grantee,privilege_type) FROM information_schema.role_table_grants WHERE table_schema='public'),
 'cross_schema_foreign_keys',(SELECT jsonb_agg(jsonb_build_object('name',c.conname,'from_schema',nf.nspname,'from_table',f.relname,'to_schema',nt.nspname,'to_table',t.relname) ORDER BY nf.nspname,f.relname,c.conname) FROM pg_constraint c JOIN pg_class f ON f.oid=c.conrelid JOIN pg_namespace nf ON nf.oid=f.relnamespace JOIN pg_class t ON t.oid=c.confrelid JOIN pg_namespace nt ON nt.oid=t.relnamespace WHERE c.contype='f' AND (nf.nspname='public' OR nt.nspname='public') AND nf.nspname<>nt.nspname)
) AS report
),counts_report AS (
WITH tables AS (
 SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT c.relispartition
), counts AS (
 SELECT relname,((xpath('string(//row_count)',query_to_xml(format('SELECT count(*) AS row_count FROM public.%I',relname),false,true,'')))[1]::text)::bigint AS row_count FROM tables
)
SELECT jsonb_build_object('report_kind','data_counts','captured_at',statement_timestamp(),'tables',coalesce(jsonb_agg(jsonb_build_object('table',relname,'row_count',row_count) ORDER BY relname),'[]'::jsonb)) AS report FROM counts
),quality_report AS (
WITH checks(name,severity,required_columns,query_sql) AS (VALUES
 ('users_missing_role_or_nonadmin_center','REVIEW','{"users": ["user_id", "role_id", "center_id"], "roles": ["role_id", "role_name"]}','WITH issues AS (SELECT u.user_id AS id FROM public.users u LEFT JOIN public.roles r USING(role_id) WHERE r.role_id IS NULL OR (r.role_name<>''Admin'' AND u.center_id IS NULL)) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('user_status_outside_current_contract','REVIEW','{"users": ["user_id", "status"]}','WITH issues AS (SELECT user_id AS id FROM public.users WHERE status IS NULL OR status NOT IN (''Active'',''Inactive'',''Locked'',''Pending'')) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('subtype_members_role_mismatch','REVIEW','{"users": ["user_id", "role_id"], "roles": ["role_id", "role_name"], "members": ["user_id"]}','WITH issues AS (SELECT p.user_id AS id FROM public.members p LEFT JOIN public.users u USING(user_id) LEFT JOIN public.roles r USING(role_id) WHERE u.user_id IS NULL OR r.role_name IS DISTINCT FROM ''Member'') SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('role_Member_missing_subtype','REVIEW','{"users": ["user_id", "role_id"], "roles": ["role_id", "role_name"], "members": ["user_id"]}','WITH issues AS (SELECT u.user_id AS id FROM public.users u JOIN public.roles r USING(role_id) LEFT JOIN public.members p USING(user_id) WHERE r.role_name=''Member'' AND p.user_id IS NULL) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('subtype_coaches_role_mismatch','REVIEW','{"users": ["user_id", "role_id"], "roles": ["role_id", "role_name"], "coaches": ["user_id"]}','WITH issues AS (SELECT p.user_id AS id FROM public.coaches p LEFT JOIN public.users u USING(user_id) LEFT JOIN public.roles r USING(role_id) WHERE u.user_id IS NULL OR r.role_name IS DISTINCT FROM ''Coach'') SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('role_Coach_missing_subtype','REVIEW','{"users": ["user_id", "role_id"], "roles": ["role_id", "role_name"], "coaches": ["user_id"]}','WITH issues AS (SELECT u.user_id AS id FROM public.users u JOIN public.roles r USING(role_id) LEFT JOIN public.coaches p USING(user_id) WHERE r.role_name=''Coach'' AND p.user_id IS NULL) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('subtype_receptionists_role_mismatch','REVIEW','{"users": ["user_id", "role_id"], "roles": ["role_id", "role_name"], "receptionists": ["user_id"]}','WITH issues AS (SELECT p.user_id AS id FROM public.receptionists p LEFT JOIN public.users u USING(user_id) LEFT JOIN public.roles r USING(role_id) WHERE u.user_id IS NULL OR r.role_name IS DISTINCT FROM ''Receptionist'') SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('role_Receptionist_missing_subtype','REVIEW','{"users": ["user_id", "role_id"], "roles": ["role_id", "role_name"], "receptionists": ["user_id"]}','WITH issues AS (SELECT u.user_id AS id FROM public.users u JOIN public.roles r USING(role_id) LEFT JOIN public.receptionists p USING(user_id) WHERE r.role_name=''Receptionist'' AND p.user_id IS NULL) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('active_subject_outside_approved_nine','REVIEW','{"subjects": ["subject_id", "slug", "status"]}','WITH issues AS (SELECT subject_id AS id FROM public.subjects WHERE status=''Active'' AND coalesce(slug,'''') NOT IN (''quan-vot-tennis'',''boi-loi'',''pickleball'',''ban-cung'',''bong-ro'',''bong-da'',''bong-chuyen'',''cau-long'',''bong-ban'')) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('active_subject_nonpositive_price','REVIEW','{"subjects": ["subject_id", "normal_price", "advanced_price", "status"]}','WITH issues AS (SELECT subject_id AS id FROM public.subjects WHERE status=''Active'' AND (normal_price IS NULL OR normal_price<=0 OR advanced_price IS NULL OR advanced_price<=0)) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('class_invalid_type_capacity_price_or_count','REVIEW','{"classes": ["class_id", "class_type", "max_capacity", "tuition_fee", "total_sessions"]}','WITH issues AS (SELECT class_id AS id FROM public.classes WHERE class_type IS NULL OR class_type NOT IN (''Normal'',''Advanced'') OR max_capacity IS NULL OR max_capacity<1 OR tuition_fee IS NULL OR tuition_fee<=0 OR total_sessions IS DISTINCT FROM 12 OR (class_type=''Normal'' AND max_capacity>15) OR (class_type=''Advanced'' AND max_capacity<>1)) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('normal_open_or_ongoing_without_twelve_valid_sessions','REVIEW','{"classes": ["class_id", "class_type", "status"], "sessions": ["session_id", "class_id", "status", "center_invalidated"]}','WITH issues AS (SELECT c.class_id AS id FROM public.classes c LEFT JOIN public.sessions s ON s.class_id=c.class_id AND s.status<>''Cancelled'' AND NOT s.center_invalidated WHERE c.class_type=''Normal'' AND c.status IN (''Open'',''Ongoing'') GROUP BY c.class_id HAVING count(s.session_id)<>12) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('session_room_class_center_or_capacity_mismatch','REVIEW','{"sessions": ["session_id", "class_id", "room_id"], "classes": ["class_id", "center_id", "max_capacity"], "rooms": ["room_id", "center_id", "capacity"]}','WITH issues AS (SELECT s.session_id AS id FROM public.sessions s JOIN public.classes c USING(class_id) JOIN public.rooms r USING(room_id) WHERE c.center_id IS DISTINCT FROM r.center_id OR c.max_capacity>r.capacity) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('future_session_wrong_room_activity','REVIEW','{"sessions": ["session_id", "class_id", "room_id", "session_date", "end_time", "status"], "classes": ["class_id", "subject_id"], "subjects": ["subject_id", "slug"], "rooms": ["room_id"], "scms_data_migration_audit": ["migration_key", "after_data"]}','WITH issues AS (WITH p(activity,slug,codes) AS (VALUES
(''TENNIS'',''quan-vot-tennis'',ARRAY[''C01-TEN-01'',''C01-TEN-02'']),(''FOOTBALL'',''bong-da'',ARRAY[''C01-FOOT-01'',''C01-FOOT-02'']),(''ARCHERY'',''ban-cung'',ARRAY[''C01-ARC-01'',''C01-ARC-02'']),(''BASKETBALL'',''bong-ro'',ARRAY[''C01-BR-01'',''C01-BR-02'']),(''VOLLEYBALL'',''bong-chuyen'',ARRAY[''C01-BC-01'',''C01-BC-02'']),(''PICKLEBALL'',''pickleball'',ARRAY[''C01-PICK-01'',''C01-PICK-02'']),(''BADMINTON'',''cau-long'',ARRAY[''C01-BAD-01'',''C01-BAD-02'']),(''TABLE_TENNIS'',''bong-ban'',ARRAY[''C01-TT-01'',''C01-TT-02'',''C01-TT-03'',''C01-TT-04'']),(''SWIMMING'',''boi-loi'',ARRAY[''C01-SWIM-01'',''C01-SWIM-02''])),
bound AS (SELECT (j->>''room_id'')::int room_id,p.activity FROM public.scms_data_migration_audit a CROSS JOIN LATERAL jsonb_array_elements(a.after_data::jsonb->''rooms'') j JOIN p ON j->>''room_code''=ANY(p.codes) WHERE a.migration_key=''20261102_room_catalog_v1'')
SELECT s.session_id AS id FROM public.sessions s JOIN public.classes c USING(class_id) JOIN public.subjects sub USING(subject_id) JOIN public.rooms r USING(room_id) LEFT JOIN bound b USING(room_id) LEFT JOIN p ON p.slug=sub.slug
WHERE s.status=''Scheduled'' AND s.session_date+s.end_time>statement_timestamp() AT TIME ZONE ''Asia/Ho_Chi_Minh''
AND (CASE WHEN EXISTS(SELECT 1 FROM public.scms_data_migration_audit WHERE migration_key=''20261109_room_activity_v1'') THEN to_jsonb(r)->>''activity_type'' ELSE coalesce(to_jsonb(r)->>''activity_type'',b.activity) END IS NULL OR CASE WHEN EXISTS(SELECT 1 FROM public.scms_data_migration_audit WHERE migration_key=''20261109_room_activity_v1'') THEN to_jsonb(r)->>''activity_type'' ELSE coalesce(to_jsonb(r)->>''activity_type'',b.activity) END IS DISTINCT FROM p.activity)) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('future_session_missing_active_coach_qualification','REVIEW','{"sessions": ["session_id", "class_id", "coach_id", "session_date", "end_time", "status"], "classes": ["class_id", "coach_id", "subject_id"], "users": ["user_id", "role_id", "status"], "roles": ["role_id", "role_name"], "coach_specializations": ["coach_id", "specialization_id"], "specializations": ["specialization_id", "subject_id", "status"]}','WITH issues AS (SELECT s.session_id AS id FROM public.sessions s JOIN public.classes c USING(class_id) LEFT JOIN public.users u ON u.user_id=coalesce(s.coach_id,c.coach_id) LEFT JOIN public.roles r USING(role_id) WHERE s.status=''Scheduled'' AND s.session_date+s.end_time>statement_timestamp() AT TIME ZONE ''Asia/Ho_Chi_Minh'' AND (u.user_id IS NULL OR u.status<>''Active'' OR r.role_name<>''Coach'' OR NOT EXISTS(SELECT 1 FROM public.coach_specializations cs JOIN public.specializations sp USING(specialization_id) WHERE cs.coach_id=u.user_id AND sp.subject_id=c.subject_id AND sp.status=''Active''))) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('sessions_outside_seven_standard_slots','REVIEW','{"sessions": ["session_id", "start_time", "end_time"]}','WITH issues AS (SELECT session_id AS id FROM public.sessions WHERE (start_time,end_time) NOT IN ((TIME ''06:00'',TIME ''07:30''),(TIME ''07:45'',TIME ''09:15''),(TIME ''09:30'',TIME ''11:00''),(TIME ''13:00'',TIME ''14:30''),(TIME ''14:45'',TIME ''16:15''),(TIME ''16:30'',TIME ''18:00''),(TIME ''18:15'',TIME ''19:45''))) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('scheduled_session_past_end_unfinalized','INFO_REVIEW_JOB_OR_SEED','{"sessions": ["session_id", "status", "session_date", "end_time", "attendance_finalized"]}','WITH issues AS (SELECT session_id AS id FROM public.sessions WHERE status=''Scheduled'' AND NOT attendance_finalized AND session_date+end_time<=statement_timestamp() AT TIME ZONE ''Asia/Ho_Chi_Minh'') SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('overlapping_noncancelled_room_sessions','REVIEW','{"sessions": ["session_id", "class_id", "room_id", "coach_id", "booked_member_id", "session_date", "start_time", "end_time", "status"], "classes": ["class_id", "coach_id"]}','WITH issues AS (SELECT a.session_id AS id FROM public.sessions a JOIN public.classes ca ON ca.class_id=a.class_id JOIN public.sessions b ON a.session_id<b.session_id AND a.session_date=b.session_date AND a.start_time<b.end_time AND a.end_time>b.start_time JOIN public.classes cb ON cb.class_id=b.class_id WHERE a.status<>''Cancelled'' AND b.status<>''Cancelled'' AND a.room_id=b.room_id) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('overlapping_noncancelled_coach_sessions','REVIEW','{"sessions": ["session_id", "class_id", "room_id", "coach_id", "booked_member_id", "session_date", "start_time", "end_time", "status"], "classes": ["class_id", "coach_id"]}','WITH issues AS (SELECT a.session_id AS id FROM public.sessions a JOIN public.classes ca ON ca.class_id=a.class_id JOIN public.sessions b ON a.session_id<b.session_id AND a.session_date=b.session_date AND a.start_time<b.end_time AND a.end_time>b.start_time JOIN public.classes cb ON cb.class_id=b.class_id WHERE a.status<>''Cancelled'' AND b.status<>''Cancelled'' AND coalesce(a.coach_id,ca.coach_id)=coalesce(b.coach_id,cb.coach_id)) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('overlapping_noncancelled_member_sessions','REVIEW','{"sessions": ["session_id", "class_id", "room_id", "coach_id", "booked_member_id", "session_date", "start_time", "end_time", "status"], "classes": ["class_id", "coach_id"]}','WITH issues AS (SELECT a.session_id AS id FROM public.sessions a JOIN public.classes ca ON ca.class_id=a.class_id JOIN public.sessions b ON a.session_id<b.session_id AND a.session_date=b.session_date AND a.start_time<b.end_time AND a.end_time>b.start_time JOIN public.classes cb ON cb.class_id=b.class_id WHERE a.status<>''Cancelled'' AND b.status<>''Cancelled'' AND a.booked_member_id=b.booked_member_id) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('advanced_session_entitlement_link_mismatch','REVIEW','{"sessions": ["session_id", "class_id", "booked_member_id", "subscription_id"], "classes": ["class_id", "subject_id", "class_type"], "member_packages": ["subscription_id", "member_id", "subject_id"]}','WITH issues AS (SELECT s.session_id AS id FROM public.sessions s JOIN public.classes c USING(class_id) LEFT JOIN public.member_packages p USING(subscription_id) WHERE c.class_type=''Advanced'' AND (s.booked_member_id IS NULL OR p.subscription_id IS NULL OR s.booked_member_id IS DISTINCT FROM p.member_id OR c.subject_id IS DISTINCT FROM p.subject_id)) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('active_advanced_without_paid_activation','REVIEW','{"member_packages": ["subscription_id", "status", "subject_id", "activated_at", "expires_at"], "invoices": ["invoice_id", "subscription_id", "payment_status", "reconciliation_required", "cash_confirmation_reversed"]}','WITH issues AS (SELECT p.subscription_id AS id FROM public.member_packages p WHERE p.status=''Active'' AND p.subject_id IS NOT NULL AND (p.activated_at IS NULL OR p.expires_at IS NULL OR NOT EXISTS(SELECT 1 FROM public.invoices i WHERE i.subscription_id=p.subscription_id AND i.payment_status=''Paid'' AND NOT i.reconciliation_required AND NOT i.cash_confirmation_reversed))) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('advanced_credit_balance_out_of_range','REVIEW','{"member_packages": ["subscription_id", "subject_id", "remaining_credit", "expiry_revoked_credit"]}','WITH issues AS (SELECT subscription_id AS id FROM public.member_packages WHERE subject_id IS NOT NULL AND (remaining_credit IS NULL OR remaining_credit<0 OR remaining_credit>12 OR coalesce(expiry_revoked_credit,0)<0)) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('normal_entitlement_without_valid_paid_invoice','REVIEW','{"class_enrollments": ["enrollment_id", "member_id", "class_id", "status"], "classes": ["class_id", "class_type"], "invoices": ["invoice_id", "member_id", "class_id", "payment_status", "reconciliation_required", "cash_confirmation_reversed"]}','WITH issues AS (SELECT e.enrollment_id AS id FROM public.class_enrollments e JOIN public.classes c USING(class_id) WHERE c.class_type=''Normal'' AND e.status IN (''Registered'',''Completed'') AND NOT EXISTS(SELECT 1 FROM public.invoices i WHERE i.member_id=e.member_id AND i.class_id=e.class_id AND i.payment_status=''Paid'' AND NOT i.reconciliation_required AND NOT i.cash_confirmation_reversed)) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('invoices_nonpositive_amount','REVIEW','{"invoices": ["invoice_id", "amount"]}','WITH issues AS (SELECT invoice_id AS id FROM public.invoices WHERE amount IS NULL OR amount<=0) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('paid_invoice_missing_payment_date','REVIEW','{"invoices": ["invoice_id", "payment_status", "payment_date"]}','WITH issues AS (SELECT invoice_id AS id FROM public.invoices WHERE payment_status=''Paid'' AND payment_date IS NULL) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('overdue_pending_invoice','INFO_REVIEW_JOB_OR_SEED','{"invoices": ["invoice_id", "payment_status", "expires_at"]}','WITH issues AS (SELECT invoice_id AS id FROM public.invoices WHERE payment_status=''Pending'' AND expires_at<statement_timestamp() AT TIME ZONE ''Asia/Ho_Chi_Minh'') SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('duplicate_current_attendance','REVIEW','{"attendances": ["attendance_id", "session_id", "member_id", "superseded_at"]}','WITH issues AS (SELECT min(attendance_id) AS id FROM public.attendances WHERE session_id IS NOT NULL AND superseded_at IS NULL GROUP BY session_id,member_id HAVING count(*)>1) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('private_attendance_wrong_member','REVIEW','{"attendances": ["attendance_id", "session_id", "member_id"], "sessions": ["session_id", "booked_member_id"]}','WITH issues AS (SELECT a.attendance_id AS id FROM public.attendances a JOIN public.sessions s USING(session_id) WHERE s.booked_member_id IS NOT NULL AND s.booked_member_id<>a.member_id) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('unsupported_attendance_state','REVIEW','{"attendances": ["attendance_id", "state"]}','WITH issues AS (SELECT attendance_id AS id FROM public.attendances WHERE state IS NULL OR state NOT IN (''Present'',''Absent'',''Late'')) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('legacy_lobby_attendance','INFO_LEGACY','{"attendances": ["attendance_id", "session_id"]}','WITH issues AS (SELECT attendance_id AS id FROM public.attendances WHERE session_id IS NULL) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('legacy_late_attendance','INFO_LEGACY','{"attendances": ["attendance_id", "state"]}','WITH issues AS (SELECT attendance_id AS id FROM public.attendances WHERE state=''Late'') SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('legacy_membership_catalog_rows','INFO_LEGACY','{"membership_packages": ["package_id"]}','WITH issues AS (SELECT package_id AS id FROM public.membership_packages) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('legacy_membership_linked_subscriptions','INFO_LEGACY','{"member_packages": ["subscription_id", "package_id"]}','WITH issues AS (SELECT subscription_id AS id FROM public.member_packages WHERE package_id IS NOT NULL) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('legacy_invoice_membership_links','INFO_LEGACY','{"invoices": ["invoice_id", "package_id"]}','WITH issues AS (SELECT invoice_id AS id FROM public.invoices WHERE package_id IS NOT NULL) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('audit_without_event_provenance','INFO_LEGACY','{"system_logs": ["log_id", "audit_category", "scope_source"]}','WITH issues AS (SELECT log_id AS id FROM public.system_logs WHERE audit_category IS NULL OR scope_source IS NULL) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('open_normal_marked_pricing_draft','REVIEW','{"classes": ["class_id", "class_type", "status", "pricing_draft"]}','WITH issues AS (SELECT class_id AS id FROM public.classes WHERE class_type=''Normal'' AND pricing_draft AND status IN (''Open'',''Ongoing'')) SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues'),
 ('users_pending_registration','INFO_OTP_LIFECYCLE','{"users": ["user_id", "status"]}','WITH issues AS (SELECT user_id AS id FROM public.users WHERE status=''Pending'') SELECT jsonb_build_object(''count'',count(*),''sample_ids'',coalesce((SELECT jsonb_agg(id) FROM (SELECT DISTINCT id FROM issues ORDER BY id LIMIT 12) s),''[]''::jsonb)) AS payload FROM issues')
)
,coverage AS (
 SELECT c.*,NOT EXISTS(SELECT 1 FROM jsonb_each(c.required_columns::jsonb) r CROSS JOIN LATERAL jsonb_array_elements_text(r.value) col
  WHERE NOT EXISTS(SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema='public' AND ic.table_name=r.key AND ic.column_name=col)) AS runnable
 FROM checks c
), results AS (
 SELECT name,severity,runnable,CASE WHEN runnable THEN ((xpath('string(//payload)',query_to_xml(query_sql,false,true,'')))[1]::text)::jsonb ELSE NULL END AS result FROM coverage
)
SELECT jsonb_build_object('report_kind','data_quality','captured_at',statement_timestamp(),
 'limits','Review findings against Owner decisions/source. INFO rows are not automatically invalid. Missing structure is NOT_RUN, not PASS; this inventory never changes rows.',
 'checks',jsonb_agg(jsonb_build_object('name',name,'severity',severity,'status',CASE WHEN NOT runnable THEN 'NOT_RUN_MISSING_STRUCTURE' WHEN (result->>'count')::bigint=0 THEN 'NO_MATCHING_ROWS' ELSE 'REVIEW_ROWS' END,'result',result) ORDER BY name)) AS report FROM results
)
SELECT jsonb_build_object('audit_version','20261109-v2','schema_inventory',(SELECT report FROM schema_report),
 'data_counts',(SELECT report FROM counts_report),'data_quality',(SELECT report FROM quality_report)) AS scms_demo_db_audit;
COMMIT;
